U.add('snd','adv_hum60',{sev:4.81,ax:{x:0.327,a:0.99},new:'transformer hum: 60, 120 and 180 Hz sines whose pitch drifts a few cents on a very slow oscillator',play:(a,o,r)=>{const R=U.au.rig(a),Q=U.cfg.adv,lf=R.osc('sine',Q.hum_lfo),lg=a.createGain();lg.gain.value=Q.hum_cents;lf.start();
 [[60,1],[120,.6],[180,.35]].forEach(([f,m])=>{const s=R.osc('sine',f),g=a.createGain();g.gain.value=Q.hum_gain*m;lf.connect(lg).connect(s.detune);s.connect(g).connect(o);s.start()});return()=>R.stop()}});
U.add('snd','adv_keyclack',{sev:4.4,ax:{x:0.224,a:0.988},new:'keystroke synthesis: every key you press clacks, the pitch of the thock set by the key code',play:(a,o,r)=>{const R=U.au.rig(a),Q=U.cfg.adv;const hum=R.osc('sine',50),hg=a.createGain();hg.gain.value=Q.clack_bed;hum.connect(hg).connect(o);hum.start();
 R.on(document,'keydown',e=>{const t=a.currentTime,s=R.src(U.au.noise(a,.03)),g=a.createGain(),b=R.osc('sine',110+((e.keyCode||65)%12)*12),bg=a.createGain();g.gain.setValueAtTime(Q.clack_gain,t);g.gain.exponentialRampToValueAtTime(.0001,t+.02);s.connect(g).connect(o);s.start(t);bg.gain.setValueAtTime(Q.clack_gain,t);bg.gain.exponentialRampToValueAtTime(.0001,t+.09);b.connect(bg).connect(o);b.start(t);b.stop(t+.1)});return()=>R.stop()}});
